import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("webpage_url must be a non-empty string")

    try:
        response = requests.get(webpage_url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Failed to fetch URL: {e}")

    try:
        tree = html.fromstring(response.content)
        table = tree.find('.//table')
        if table is None:
            return 0

        headers = [th.text_content().strip() for th in table.findall('.//th')]

        rows = []
        for tr in table.findall('.//tr'):
            cols = [td.text_content().strip() for td in tr.findall('.//td')]
            if cols:
                rows.append(cols)

        if not rows:
            return 0

        df = pd.DataFrame(rows, columns=headers if headers else None)
    except Exception as e:
        raise ValueError(f"Error parsing HTML: {e}")

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.close()
    except sqlite3.Error as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

    return len(df)

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        return 0
    try:
        response = requests.get(webpage_url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network error accessing URL: {e}")
    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')[0]
        rows = table.xpath('.//tr')
        if not rows:
            return 0
        headers = [th.text_content().strip() for th in rows[0].xpath('.//th')]
        data = []
        for row in rows[1:]:
            cols = row.xpath('.//td')
            if cols:
                data.append([col.text_content().strip() for col in cols])
        if not data:
            return 0
        df = pd.DataFrame(data, columns=headers if headers else None)
    except Exception:
        return 0
    try:
        conn = sqlite3.connect(database_name)
        cursor = conn.cursor()
        cursor.execute("DROP TABLE IF EXISTS my_table")
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.commit()
        row_count = len(df)
        conn.close()
        return row_count
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

