import requests
import os
import zipfile
def task_func(url, destination_directory, headers=None):
    if not url or not destination_directory:
        raise ValueError("URL and destination_directory must be non-empty.")

    try:
        response = requests.get(url, headers=headers, stream=True)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download zip file: {e}")

    os.makedirs(destination_directory, exist_ok=True)

    try:
        with zipfile.ZipFile(response.raw) as zf:
            zf.extractall(destination_directory)
            extracted_files = zf.namelist()
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {e}")

    return extracted_files

import requests
import os
import zipfile
def task_func(url, destination_directory, headers=None):
    if not url:
        raise ValueError("URL must be provided.")
    if not os.path.exists(destination_directory):
        os.makedirs(destination_directory)

    try:
        response = requests.get(url, headers=headers, stream=True)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download file: {e}")

    zip_path = os.path.join(destination_directory, 'temp.zip')
    with open(zip_path, 'wb') as f:
        for chunk in response.iter_content(chunk_size=8192):
            f.write(chunk)

    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(destination_directory)
    except zipfile.BadZipFile as e:
        raise IOError(f"Failed to extract zip file: {e}")
    finally:
        os.remove(zip_path)

    extracted_files = [f for f in os.listdir(destination_directory) if os.path.isfile(os.path.join(destination_directory, f))]
    return extracted_files

